module OneHotMux__U ( input logic [19:0] in [7:0], input logic [7:0] sel, output logic [19:0] out ); always_comb begin out = in[0]; unique case (1'b1) sel[0]: out = in [0]; sel[1]: out = in [1]; sel[2]: out = in [2]; sel[3]: out = in [3]; sel[4]: out = in [4]; sel[5]: out = in [5]; sel[6]: out = in [6]; sel[7]: out = in [7]; endcase assert ($onehot(sel)) else $error("select is not one hot"); end endmodule
